globalThis.patrimoineProjects ??= {};
globalThis.patrimoineProjects.village = {"title":"Visite du village de Marquixanes","map":"data:image/jpeg;base64,","points":[{"number":1,"x":51.5,"y":40.2,"title":"Église Sainte-Eulalie et Sainte-Julie","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"L’église Sainte-Eulalie et Sainte-Julie fait partie du cœur historique de Marquixanes. La fiche présente son histoire et son architecture.","transcriptEn":"The church of Saint Eulalia and Saint Julia stands in the historic heart of Marquixanes. The panel introduces its history and architecture.","transcriptCa":"L’església de Santa Eulàlia i Santa Júlia és al cor històric de Marqueixanes. La fitxa en presenta la història i l’arquitectura.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":2,"x":46.1,"y":38.2,"title":"Une mémoire révélée","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Le plan de 1811 et les vestiges de l’ancien abattoir éclairent l’histoire de ce secteur du village.","transcriptEn":"The 1811 map and the remains of the former slaughterhouse shed light on this part of the village.","transcriptCa":"El plànol de 1811 i els vestigis de l’antic escorxador ens expliquen la història d’aquest sector del poble.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":3,"x":49.2,"y":37.8,"title":"La cellera et la porte à bretèche","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La cellera s’est développée autour de l’église. Observez la porte à bretèche, qui rappelle la fonction défensive de cette enceinte.","transcriptEn":"The cellera grew up around the church. Look at the gate with its projecting defensive structure, a reminder of the enclosure’s purpose.","transcriptCa":"La cellera es va desenvolupar al voltant de l’església. Fixeu-vos en el portal amb lladronera, que recorda la funció defensiva del recinte.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":4,"x":43.2,"y":36.5,"title":"La Roque","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Depuis la Roque, observez le panorama et suivez sur la fiche le tracé de la Via Conflentana.","transcriptEn":"Enjoy the panorama from La Roque and follow the route of the Via Conflentana on the panel.","transcriptCa":"Des de la Roca, contempleu el paisatge i seguiu a la fitxa el traçat de la Via Conflentana.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":5,"x":60.5,"y":32.8,"title":"Les fortifications de la rue des Remparts","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Dans la rue des Remparts, observez les traces des anciennes fortifications du village.","transcriptEn":"On Rue des Remparts, look for traces of the village’s former fortifications.","transcriptCa":"Al carrer de les Muralles, observeu les traces de les antigues fortificacions del poble.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":6,"x":67,"y":37.6,"title":"Le four à pain du carrer del Figueral","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Le four à pain du carrer del Figueral rappelle la place du pain dans la vie quotidienne du village.","transcriptEn":"The bread oven on Carrer del Figueral recalls the importance of bread in everyday village life.","transcriptCa":"El forn de pa del carrer del Figueral recorda la importància del pa en la vida quotidiana del poble.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":7,"x":64.1,"y":37.6,"title":"La porte Est et l’ancien presbytère","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La porte Est et l’ancien presbytère témoignent des transformations du village. La fiche aide à retrouver leur emplacement.","transcriptEn":"The east gate and the former rectory reflect changes in the village. The panel helps you locate them.","transcriptCa":"El portal de llevant i l’antiga rectoria són testimonis dels canvis del poble. La fitxa us ajuda a situar-los.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":8,"x":60.1,"y":45.6,"title":"Carrer del Saby","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Cette halte du carrer del Saby évoque le four à pain et rappelle le souvenir de Latour-Natal.","transcriptEn":"This stop on Carrer del Saby recalls the bread oven and the story of Latour-Natal.","transcriptCa":"Aquesta parada al carrer del Saby evoca el forn de pa i recorda Latour-Natal.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":9,"x":52.2,"y":46.3,"title":"Rue Notre-Dame et l’ancien hospice des pauvres","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La rue Notre-Dame conserve le souvenir de l’ancien hospice des pauvres et de sa fonction d’accueil.","transcriptEn":"Rue Notre-Dame preserves the memory of the former hospice and its role in caring for people in need.","transcriptCa":"El carrer de Nostra Senyora conserva el record de l’antic hospici dels pobres i de la seva funció d’acollida.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":10,"x":48.5,"y":45.2,"title":"La maison traditionnelle de la rue du Centre","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Observez la façade de cette maison traditionnelle. La planche présente les détails qui racontent son histoire.","transcriptEn":"Look at the frontage of this traditional house. The panel shows details that tell its story.","transcriptCa":"Observeu la façana d’aquesta casa tradicional. La fitxa en presenta els detalls que n’expliquen la història.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":11,"x":40.3,"y":41,"title":"La porte Ouest et la rue du Porche","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La porte Ouest est l’un des anciens accès au village. La rue du Porche permet encore de lire l’organisation du bourg médiéval.","transcriptEn":"The west gate is one of the village’s historic entrances. Rue du Porche still shows how the medieval settlement was laid out.","transcriptCa":"El portal de ponent és un dels antics accessos al poble. El carrer del Porxo encara permet entendre com s’organitzava la vila medieval.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":12,"x":33.6,"y":39.1,"title":"La fontaine, le lavoir et le four à pain","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La fontaine, le lavoir et le four à pain rappellent les activités partagées de la vie quotidienne.","transcriptEn":"The fountain, the washhouse and the bread oven recall the shared activities of everyday life.","transcriptCa":"La font, el safareig i el forn de pa recorden les activitats compartides de la vida quotidiana.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":13,"x":45.2,"y":48.5,"title":"Le renfort de rempart","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Face à l’ancienne poste, le renfort de rempart témoigne du rôle défensif de l’enceinte du village.","transcriptEn":"Opposite the old post office, the reinforced wall recalls the defensive role of the village enclosure.","transcriptCa":"Davant de l’antiga oficina de correus, el reforç de la muralla recorda la funció defensiva del recinte del poble.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":14,"x":50.8,"y":52.2,"title":"Les portes anciennes de la rue du Centre","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Les portes anciennes de la rue du Centre permettent d’observer les formes et les matériaux de l’habitat du village.","transcriptEn":"The old doorways on Rue du Centre show the shapes and materials used in the village’s houses.","transcriptCa":"Els portals antics del carrer del Centre permeten observar les formes i els materials de les cases del poble.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":15,"x":53,"y":54.5,"title":"La mairie, l’ancien cimetière et la chapelle Saint-Pons","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La fiche retrace les usages successifs de ce secteur, entre la mairie actuelle, l’ancien cimetière et la chapelle Saint-Pons.","transcriptEn":"The panel traces the different uses of this area around today’s town hall, the former cemetery and Saint Pons Chapel.","transcriptCa":"La fitxa explica els diferents usos d’aquest indret, entre l’ajuntament actual, l’antic cementiri i la capella de Sant Ponç.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":16,"x":56.2,"y":56.3,"title":"Le monument aux morts","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Le monument aux morts perpétue la mémoire des habitants du village morts lors des guerres de 1914 et de 1939.","transcriptEn":"The war memorial honours villagers who died in the two world wars.","transcriptCa":"El monument als caiguts manté viu el record dels habitants del poble que van morir a les dues guerres mundials.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":17,"x":56.2,"y":61.7,"title":"Le Christ de Mission de 1895","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Plus de 130 ans après son élévation, ce Christ de Mission reste un témoin de la vie religieuse et villageoise de Marquixanes à la fin du dix-neuvième siècle.","transcriptEn":"More than 130 years after it was erected, this Mission Cross still bears witness to religious and village life in late nineteenth-century Marquixanes.","transcriptCa":"Més de cent trenta anys després de la seva instal·lació, aquest Crist de Missió continua sent un testimoni de la vida religiosa i del poble de Marqueixanes a finals del segle dinou.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":18,"x":53.6,"y":63.8,"title":"La chapelle Saint-Pons et le cimetière","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La chapelle Saint-Pons et le cimetière conservent une part de la mémoire religieuse et familiale du village.","transcriptEn":"Saint Pons Chapel and the cemetery preserve part of the village’s religious and family history.","transcriptCa":"La capella de Sant Ponç i el cementiri conserven una part de la memòria religiosa i familiar del poble.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":19,"x":61.8,"y":52.2,"title":"Carrer del Saby, la pompe et la niche Saint-Jean-Baptiste","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Sur le carrer del Saby, cherchez la pompe et la niche dédiée à saint Jean-Baptiste.","transcriptEn":"On Carrer del Saby, look for the pump and the niche dedicated to Saint John the Baptist.","transcriptCa":"Al carrer del Saby, busqueu la bomba d’aigua i el nínxol dedicat a sant Joan Baptista.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":20,"x":70,"y":22.8,"title":"Roger Roquefort","offMap":false,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Près de l’ancienne gare, la stèle rend hommage à Roger Roquefort, résistant, mort pour la France en 1944.","transcriptEn":"Near the former railway station, the memorial pays tribute to Roger Roquefort, a member of the Resistance who died for France in 1944.","transcriptCa":"A prop de l’antiga estació, l’estela ret homenatge a Roger Roquefort, membre de la Resistència, mort per França el 1944.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":21,"x":50,"y":50,"title":"Les travaux agricoles au Moyen Âge · 1200–1600","offMap":true,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Du treizième au seizième siècle, les habitants cultivent des céréales, des vignes, des oliviers, des jardins et des vergers autour de la cellera. Les saisons rythment le travail manuel.","transcriptEn":"From the thirteenth to the sixteenth century, villagers grow cereals, vines and olives and tend gardens and orchards around the cellera. Manual work follows the seasons.","transcriptCa":"Del segle tretze al setze, els habitants conreen cereals, vinyes i oliveres i tenen horts i vergers al voltant de la cellera. Les estacions marquen el ritme del treball manual.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":22,"x":50,"y":50,"title":"La terre et la force animale · 1659–1900","offMap":true,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Après le traité des Pyrénées de 1659, les bœufs, les mulets et les chevaux aident à labourer, transporter et récolter. Le blé, la vigne, l’olivier, les jardins et les vergers composent une polyculture vivrière.","transcriptEn":"After the Treaty of the Pyrenees in 1659, oxen, mules and horses help plough, carry goods and bring in the harvest. Wheat, vines, olives, gardens and orchards provide a variety of food.","transcriptCa":"Després del tractat dels Pirineus de 1659, els bous, les mules i els cavalls ajuden a llaurar, transportar i collir. El blat, la vinya, l’olivera, els horts i els vergers mantenen una agricultura de subsistència diversificada.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":23,"x":50,"y":50,"title":"L’âge d’or des vergers et la traction mécanique · 1900–2000","offMap":true,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"Au vingtième siècle, le tracteur transforme le travail agricole. À partir de 1950, les abricotiers, les pêchers et les nectariniers prennent une place croissante dans les vergers de Marquixanes.","transcriptEn":"In the twentieth century, tractors transform farm work. From 1950 onwards, apricot, peach and nectarine trees become increasingly important in the orchards of Marquixanes.","transcriptCa":"Al segle vint, el tractor transforma la feina al camp. A partir de 1950, els albercoquers, els presseguers i els nectariners guanyen terreny als vergers de Marqueixanes.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"},{"number":24,"x":50,"y":50,"title":"La terre face aux nouveaux défis climatiques · 2000–2026","offMap":true,"extra":[],"image":"data:image/jpeg;base64,","text":"","source":"","transcript":"La sécheresse, le manque d’eau et les fortes chaleurs fragilisent l’agriculture locale. L’olivier retrouve une place visible, tandis que le grenadier et le figuier ouvrent de nouvelles pistes.","transcriptEn":"Drought, water shortages and extreme heat put local farming under pressure. Olive trees are becoming more visible again, while pomegranates and figs offer new possibilities.","transcriptCa":"La sequera, l’escassetat d’aigua i les fortes calors posen a prova l’agricultura local. L’olivera torna a guanyar presència, i el magraner i la figuera obren noves possibilitats.","audio":"","audioEn":"","audioCa":"data:audio/wav;base64,"}]};
